import { Router } from 'express';
import { authMiddleware } from '../middleware/auth.js';

const router = Router();

// Додаємо authMiddleware до існуючого роута
router.get('/:id', authMiddleware, (req, res) => {
  // existing user endpoint
  res.json({ id: req.params.id, name: 'User' });
});

// Новий route для профілю з авторизацією
router.get('/:id/profile', authMiddleware, (req, res) => {
  res.json({ id: req.params.id, profile: { bio: 'User bio' } });
});

export default router;
